mapper.select:
SELECT c.id AS id, c.user_id AS user_id, c.body AS body, c.status AS status, c.created_at AS created_at, u.public_id AS public_id, u.display_name AS display_name, u.avatar_url AS avatar_url FROM comments c JOIN users u ON u.id = c.user_id WHERE c.episode_id = #{episodeId}
AND (c.status = 'approved' OR (c.status = 'pending' AND c.user_id = #{userId}))
AND c.status = 'approved'
AND c.id < #{cursor}
ORDER BY c.id DESC LIMIT #{limit}

SELECT COUNT(*) FROM comments
WHERE episode_id = #{episodeId}
  AND status = 'pending'
  AND user_id = #{userId}

SELECT id FROM comments
WHERE user_id = #{userId}
  AND episode_id = #{episodeId}
  AND created_at >= #{since}
LIMIT 1
